/// <summary>
/// All fields are optional; omitted ones take the defaults shown. The Opus fields become the
/// `AudioPolicy` delivered to participants in `ChannelJoinAck.audio` (and `ChannelAudioPolicy` on
/// live edits).
/// </summary>
public sealed record ChannelConfig
{
    [JsonPropertyName("channel_type")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? ChannelType { get; init; }

    [JsonPropertyName("max_participants")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public long? MaxParticipants { get; init; }

    [JsonPropertyName("codec")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Codec { get; init; }

    /// <summary>
    /// Target uplink Opus bitrate in bit/s (also the ceiling server-driven adaptation returns to).
    /// Capped by the node's `media.max_bitrate`.
    /// </summary>
    [JsonPropertyName("bitrate")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public long? Bitrate { get; init; }

    /// <summary>
    /// Floor for server-driven bitrate adaptation (bit/s); must not exceed `bitrate`.
    /// </summary>
    [JsonPropertyName("min_bitrate")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public long? MinBitrate { get; init; }

    [JsonPropertyName("sample_rate")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public long? SampleRate { get; init; }

    /// <summary>
    /// Allow discontinuous transmission (silence frames are not sent).
    /// </summary>
    [JsonPropertyName("enable_dtx")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public bool? EnableDtx { get; init; }

    /// <summary>
    /// Require in-band forward error correction on the uplink.
    /// </summary>
    [JsonPropertyName("enable_fec")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public bool? EnableFec { get; init; }

    [JsonPropertyName("max_bandwidth")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? MaxBandwidth { get; init; }

    /// <summary>
    /// Encoder complexity hint 0..=10 (`null`: the client's default). Browsers ignore it.
    /// </summary>
    [JsonPropertyName("complexity")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public long? Complexity { get; init; }

    [JsonPropertyName("positional_config")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public PositionalConfig? PositionalConfig { get; init; }

    /// <summary>
    /// Cocktail-party mode; absent/`null` (default) delivers every audible speaker at full gain.
    /// </summary>
    [JsonPropertyName("ambient")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public AmbientConfig? Ambient { get; init; }

    /// <summary>
    /// Priority-speaker ducking; absent/`null` (default) disables it (priority flags are still tracked
    /// and disclosed). Disclosed to members as `ChannelJoinAck.ducking`.
    /// </summary>
    [JsonPropertyName("ducking")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public DuckingConfig? Ducking { get; init; }

    /// <summary>
    /// Large-channel / audience mode: hidden listeners, server mix for listeners, speaker admission
    /// cap, per-receiver stream cap. Absent/`null` (default): plain channel.
    /// </summary>
    [JsonPropertyName("audience")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public AudienceConfig? Audience { get; init; }

    [JsonPropertyName("audio_profile")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? AudioProfile { get; init; }

    /// <summary>
    /// Participants may send two-channel (stereo) Opus (music, DJ, broadcast sources); delivered to
    /// clients as `audio.stereo`. Off: clients encode mono. The SFU forwards either; stereo receivers
    /// keep the image, mono receivers and server-side recording/STT downmix. Recordings started while
    /// this is on are written with a 2-channel OpusHead.
    /// </summary>
    [JsonPropertyName("stereo")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public bool? Stereo { get; init; }

    [JsonPropertyName("recording_enabled")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public bool? RecordingEnabled { get; init; }

    /// <summary>
    /// Transcribe speech (when `[stt]` is configured on the node) and deliver `Transcript` events.
    /// </summary>
    [JsonPropertyName("transcription")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public bool? Transcription { get; init; }

    /// <summary>
    /// Send the speakers' transcripts to the `[safety]` classifier (requires `[stt]`); disclosed to
    /// clients as `ChannelJoinAck.safety_voice`. Independent of `transcription`.
    /// </summary>
    [JsonPropertyName("safety_voice")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public bool? SafetyVoice { get; init; }

    /// <summary>
    /// End-to-end encrypted: frames are sealed with per-sender group keys the node never sees, so it
    /// only relays them (no server mix, recording, transcription, safety, TTS or translation;
    /// incompatible with `recording_enabled`, `transcription`, `safety_voice`, `ambient`, `audience`
    /// mixing and the `echo` type). Only sessions that announced E2EE support (`E2eeHello`) may join
    /// (`E2EE_REQUIRED`); a WebRTC session cannot mix encrypted and plaintext channels
    /// (`E2EE_MIXED_CHANNELS`). Disclosed as `ChannelJoinAck.audio.e2ee`.
    /// </summary>
    [JsonPropertyName("e2ee")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public bool? E2ee { get; init; }

    [JsonPropertyName("whisper_target")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? WhisperTarget { get; init; }

    [JsonPropertyName("command_speakers")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public List<string>? CommandSpeakers { get; init; }
}

