/// <summary>
/// Merged view of the client's `QualityReport` and the SFU's uplink measurements; the worse
/// direction decides the rating (`R ≥ 80 → 5 bars, ≥ 70 → 4, ≥ 60 → 3, ≥ 50 → 2, else 1`).
/// </summary>
public sealed record NetworkQuality
{
    [JsonPropertyName("bars")]
    public required long Bars { get; init; }

    [JsonPropertyName("r_factor")]
    public required double RFactor { get; init; }

    [JsonPropertyName("mos")]
    public required double Mos { get; init; }

    [JsonPropertyName("rtt_ms")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public double? RttMs { get; init; }

    [JsonPropertyName("downlink_jitter_ms")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public double? DownlinkJitterMs { get; init; }

