/// <summary>
/// The least-loaded healthy node of one region that advertises a public WebSocket URL
/// (`server.external_ws_url`). Connect the SDK to `ws_url`; `GET probe_url` is a cheap public
/// request answered by exactly this node, so its round-trip time is a fair RTT estimate.
/// </summary>
public sealed record RegionEndpoint
{
    [JsonPropertyName("region")]
    public required string Region { get; init; }

    [JsonPropertyName("node_id")]
    public required string NodeId { get; init; }

    /// <summary>
    /// WebSocket control-plane URL of the node (`wss://…/ws`). Session resume must reach the same node,
    /// so this is a per-node URL, not a load balancer.
    /// </summary>
    [JsonPropertyName("ws_url")]
    public required string WsUrl { get; init; }

    /// <summary>
    /// `&lt;api_url&gt;/health` of the node, for client-side RTT measurement.
    /// </summary>
    [JsonPropertyName("probe_url")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? ProbeUrl { get; init; }

    [JsonPropertyName("location")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public GeoLocation? Location { get; init; }

    /// <summary>
    /// Great-circle distance from the caller's declared location, when both are known.
    /// </summary>
    [JsonPropertyName("distance_km")] [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public double? DistanceKm { get; init; }

    /// <summary>
    /// Healthy, non-saturated nodes advertising a WebSocket URL in this region.
    /// </summary>
    [JsonPropertyName("nodes")]
    public required long Nodes { get; init; }

    /// <summary>
    /// `active_participants / capacity` of the selected node (0–1).
    /// </summary>
    [JsonPropertyName("load_factor")]
    public required double LoadFactor { get; init; }
}

public sealed record RegionsResponse
{
    /// <summary>
    /// Best-first: the preferred region if it has capacity, then by distance to the declared location
    /// (regions without coordinates last), then by load. Clients that can measure RTT should probe
